xunit.pseudocode:
def run_suite(test_cases):
    result = {'pass': 0, 'fail': 0, 'error': 0}
    for case in test_cases:
        fixture = case.setUp()  # 픽스처 준비
        try:
            case.test(fixture)  # 내부 assert로 자동 판정
            result['pass'] += 1
        except AssertionError:
            result['fail'] += 1  # 기대값 불일치
        except Exception:
            result['error'] += 1  # 예기치 않은 예외
        finally:
            case.tearDown(fixture)  # 항상 정리
    return result
